            scrollView.heightAnchor.constraint(greaterThanOrEqualToConstant: 60),

            shortcutLabel.topAnchor.constraint(equalTo: scrollView.bottomAnchor, constant: 8),
            shortcutLabel.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 20),
            shortcutLabel.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -20),
            shortcutLabel.bottomAnchor.constraint(lessThanOrEqualTo: container.bottomAnchor, constant: -12)
        ])

        window?.initialFirstResponder = textView
    }

    func show() {
        guard let window = window else { return }
        window.orderFrontRegardless()
        window.makeKey()
        window.makeFirstResponder(textView)
        let end = textView.string.count
        textView.setSelectedRange(NSRange(location: end, length: 0))
    }
}

private final class LockedWhiteNoteTextView: NSTextView {
    var keyCommandHandler: ((KeyCommand) -> Void)?
    private var isApplyingFixedTextStyle = false

    override init(frame frameRect: NSRect, textContainer container: NSTextContainer?) {
        if let container {
            super.init(frame: frameRect, textContainer: container)
        } else {
            let textStorage = NSTextStorage()
            let layoutManager = NSLayoutManager()
            let textContainer = NSTextContainer(size: NSSize(width: frameRect.width, height: .greatestFiniteMagnitude))
            textContainer.widthTracksTextView = true
            textContainer.heightTracksTextView = false
            layoutManager.addTextContainer(textContainer)
            textStorage.addLayoutManager(layoutManager)
            super.init(frame: frameRect, textContainer: textContainer)
        }

        isEditable = true
        isSelectable = true
        isVerticallyResizable = true
        isHorizontallyResizable = false
        autoresizingMask = [.width]
        textContainerInset = NSSize(width: 4, height: 4)
        textContainer?.widthTracksTextView = true

    // Place it under the canvas so its position matches the final saved image.
    if let noteView = makeNotePreviewView() {
        notePreviewContainer = noteView
        rootStack.addArrangedSubview(noteView)
        noteView.translatesAutoresizingMaskIntoConstraints = false
        noteView.widthAnchor.constraint(equalTo: rootStack.widthAnchor).isActive = true
    }

    canvasView.onKeyCommand = { [weak self] command in
        self?.handleKeyCommand(command)
    }

    setupColorPicker()

    selectTool(.pen)
    selectColor(index: 0)
}

private func makeNotePreviewView() -> NSView? {
    let raw = (notePreviewRaw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    guard !raw.isEmpty else { return nil }

    // Match note burning rules (prefix + 1000 char cap), but do not modify the image here.
    var text = String(raw.prefix(1000))
    let settings = settingsStore.settings
    if settings.notePrefixEnabled {
        let prefix = settings.notePrefix.trimmingCharacters(in: .whitespacesAndNewlines)
        if !prefix.isEmpty {
            text = prefix + " " + text
        }
    }

    let container = NSView()

    let label = NSTextField(wrappingLabelWithString: text)
    label.font = NSFont.systemFont(ofSize: 13, weight: .regular)
    label.textColor = NSColor.labelColor
    label.lineBreakMode = .byWordWrapping
    label.maximumNumberOfLines = 0
    label.translatesAutoresizingMaskIntoConstraints = false

    container.addSubview(label)
    NSLayoutConstraint.activate([
        label.topAnchor.constraint(equalTo: container.topAnchor, constant: 10),
        label.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 12),
        label.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -12),
        label.bottomAnchor.constraint(equalTo: container.bottomAnchor, constant: -10)
    ])

    return container

import AppKit

/// Routes command-key equivalents before AppKit's window/menu handling can
/// consume them. The canvas remains the first responder during normal editing;
/// inline text editors intentionally keep their standard text undo manager.
final class EditorWindow: NSWindow {
    override func performKeyEquivalent(with event: NSEvent) -> Bool {
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        let chars = event.charactersIgnoringModifiers?.lowercased()

        if chars == "z", let canvas = firstResponder as? EditorCanvasView {
            if flags == [.command] {
                canvas.undo()
                return true
            }
            if flags == [.command, .shift] {
                canvas.redo()
                return true
            }
        }

        return super.performKeyEquivalent(with: event)
    }
}

/// Window controller for the screenshot editor.
///
/// The editor provides basic annotation tools (pen, arrow, rectangle,
/// ellipse, text), a small color palette with keyboard access, an undo
/// stack, and zoom controls. When the user finishes (save, copy+save,
/// copy+delete, delete), the controller calls `onComplete` with the
/// final image and desired action. The caller (ScreenshotWorkflowController)
/// is responsible for writing the image to disk, clipboard operations,
/// and backup/delete semantics.
final class EditorWindowController: NSWindowController {
    /// Called when the user finishes editing.
    /// - Parameters:
    ///   - image: The final composited image, or `nil` for delete-only.
    ///   - action: The requested final action.
    var onComplete: ((NSImage?, ScreenshotFinalAction, EditorCanvasState?) -> Void)?

/// whole canvas points. This is the full-export crop.
static func exportBounds(of drawing: EditorDrawing) -> NSRect {
    var unionRect = drawing.baseImageBounds
    for item in drawing.items {
        guard let itemBounds = bounds(for: item) else { continue }
        unionRect = unionRect.union(itemBounds)
    }
    return normalizedRect(unionRect)
}

/// Points-to-pixels ratio of the base image, so edited output keeps the
/// screenshot's native resolution instead of the screen's backing scale.
private static func baseImagePixelScale(of image: NSImage) -> CGFloat {
    let pointWidth = image.size.width
    guard pointWidth > 0 else { return 1 }
    let scale = baseImagePixelSize(of: image).width / pointWidth
    return scale > 0 ? scale : 1
}

private static func baseImagePixelSize(of image: NSImage) -> NSSize {
    let largest = image.representations
        .compactMap { $0 as? NSBitmapImageRep }
        .max(by: { lhs, rhs in
            (ImageSafety.pixelCount(width: lhs.pixelsWide, height: lhs.pixelsHigh) ?? 0)
                < (ImageSafety.pixelCount(width: rhs.pixelsWide, height: rhs.pixelsHigh) ?? 0)
        })
    if let largest {
        return NSSize(width: CGFloat(largest.pixelsWide), height: CGFloat(largest.pixelsHigh))
    }
    return image.size
